package ipl.sable.dim; import java.util.*; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.Level; import net.minecraft.core.BlockPos; import dev.ryanhcode.sable.sublevel.SubLevel; public class IplWorldFrameContext { private static ThreadLocal<ServerLevel> value=new ThreadLocal<>(); private static final ThreadLocal<Boolean> rolling=new ThreadLocal<>(); public static Map<BlockPos,ServerLevel> owners=new HashMap<>(); public static ServerLevel current(){return value.get();} public static ServerLevel push(ServerLevel v){var prev=value.get();value.set(v);return prev;} public static void pop(ServerLevel v){if(v==null)value.remove();else value.set(v);} public static ServerLevel resolveParentForPlotBe(Level l,BlockPos pos){return l.storage?owners.get(pos):null;} public static boolean rollingActive(){return Boolean.TRUE.equals(rolling.get());} static void setRolling(boolean r){if(r)rolling.set(Boolean.TRUE);else rolling.remove();} /** Production rolling branch of notifyPlotResolved (no packet frame open). */ public static void notifyPlotResolved(SubLevel sub){if(rollingActive())IplSubLevelReadViews.followResolvedShip(sub);} }
